{"task_id": "T05", "code": "def solve(grid):
    """Count the number of islands (connected components of 1's) in a 2D grid.
    Cells are connected orthogonally (up, down, left, right).
    Args:
        grid (list[list[int]]): 2D list of 0s and 1s.
    Returns:
        int: Number of islands.
    """
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    if rows == 0 or cols == 0:
        return 0
    visited = [[False] * cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            # explore neighbors
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny] and grid[nx][ny] == 1:
                    stack.append((nx, ny))
    islands = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                islands += 1
                dfs(i, j)
    return islands"}

