def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search (O(n log n))."""
    if not nums:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an inc subseq of length i+1
    for x in nums:
        # find leftmost index where tails[idx] >= x (since strictly increasing, we replace at >=)
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

