def solve(coins, amount):
    """Return fewest number of coins to make amount, unlimited supply, or -1 if impossible."""
    if amount < 0:
        return -1
    # DP array of size amount+1, init large
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            continue
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != float('inf') else -1

