def solve(tokens):
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/') and not (t.lstrip('-').isdigit()):
            # operator
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # division, truncate toward zero without float
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                sign = -1 if (a < 0) ^ (b < 0) else 1
                res = abs(a) // abs(b)
                stack.append(sign * res)
        else:
            # number token (could be negative)
            stack.append(int(t))
    return stack[0] if stack else 0

