def solve(coins, amount):
    """Return the fewest number of coins needed to make up ``amount`` using unlimited
    coins from ``coins``. If impossible, return -1.
    Uses a classic DP approach with O(amount * len(coins)) time.
    """
    if amount < 0:
        return -1
    # DP array where dp[i] is min coins for amount i; initialize with a large number.
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                dp[a] = min(dp[a], dp[a - c] + 1)
    return dp[amount] if dp[amount] != INF else -1

