def solve(tokens):
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/') and len(token) == 1:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # '/'
                # Truncate toward zero
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[-1] if stack else 0

def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Uses O(n log n) patience sorting algorithm.
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subseq of length i+1
    for x in nums:
        # Find position to replace in tails
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

